package io.scenariomesh.config; import java.nio.file.*;import java.time.*;import java.util.*;
/** Single precedence implementation: CLI > system property > environment > config-file values > Maven plugin values > defaults. */
public final class ConfigResolver { public ScenarioMeshConfig resolve(Map<String,String> cli,Map<String,String> sys,Map<String,String> env,Map<String,String> file,Map<String,String> plugin){var d=ScenarioMeshConfig.defaults(); return new ScenarioMeshConfig(bool(v("enabled",cli,sys,env,file,plugin),d.enabled()),integer(v("workers.count",cli,sys,env,file,plugin),d.workerCount()),mode(v("workers.mode",cli,sys,env,file,plugin),d.workerMode()),duration(v("workers.lifecycle.idleTimeout",cli,sys,env,file,plugin),d.idleTimeout()),integer(v("workers.lifecycle.maxScenariosPerWorker",cli,sys,env,file,plugin),d.maxScenariosPerWorker()),bool(v("workers.lifecycle.restartOnBuildChange",cli,sys,env,file,plugin),d.restartOnBuildChange()),duration(v("heartbeat.interval",cli,sys,env,file,plugin),d.heartbeatInterval()),duration(v("heartbeat.unhealthyAfter",cli,sys,env,file,plugin),d.unhealthyAfter()),or(v("scheduling.strategy",cli,sys,env,file,plugin),d.schedulingStrategy()),Path.of(or(v("reporting.directory",cli,sys,env,file,plugin),d.reportingDirectory().toString())),bool(v("runtime.autoStartDaemon",cli,sys,env,file,plugin),d.autoStartDaemon()),d.jvmArgs());}
 private String v(String k,Map<String,String>...m){for(var x:m){String y=x.get(k);if(y!=null)return y;}return null;} private String or(String v,String d){return v==null?d:v;} private int integer(String v,int d){return v==null?d:Integer.parseInt(v);} private boolean bool(String v,boolean d){return v==null?d:Boolean.parseBoolean(v);} private Duration duration(String v,Duration d){return v==null?d:Duration.parse(v);} private ScenarioMeshConfig.WorkerMode mode(String v,ScenarioMeshConfig.WorkerMode d){return v==null?d:ScenarioMeshConfig.WorkerMode.valueOf(v.toUpperCase(Locale.ROOT));}}
